import definePlugin, { StartAt } from "@utils/types";
import { findByProps, findStore } from "@webpack";
import { ChannelStore, FluxDispatcher, RestAPI, SelectedChannelStore, UserStore, UserUtils } from "@webpack/common";

declare global {
    interface Window {
        __vrTimer?: ReturnType<typeof setInterval>;
        __vrHeartbeat?: ReturnType<typeof setInterval>;
        __vrCleanup?: () => void;
        __vrTest?: (name?: string, permanent?: boolean) => void;
    }
}

export default definePlugin({
    name: "VoiceReconnect",
    description: "يرجعك لآخر روم صوتي، ينبهك بأنميشن إذا أحد طلعك أو انقطع النت، ويسألك ترجع أو تقعد إذا أحد نقلك",
    authors: [{ name: "xFaiS", id: 0n }],
    enabledByDefault: true,
    startAt: StartAt.WebpackReady,

    start() {
        const VoiceActions = findByProps("selectVoiceChannel");
        const VoiceStateStore = findStore("VoiceStateStore");
        const KEY = "VoiceReconnect_last";
        const log = (...a) => console.log("[VoiceReconnect]", ...a);

        log("started", !!VoiceActions, !!VoiceStateStore, !!SelectedChannelStore, !!ChannelStore, !!UserStore, !!FluxDispatcher, !!RestAPI);

        let lastChannel: string | null = null;
        let lastGuild: string | null = null;
        let needNetRejoin = false;
        const timers = new Set<ReturnType<typeof setTimeout>>();
        const later = (fn: () => void, ms: number) => { const t = setTimeout(() => { timers.delete(t); fn(); }, ms); timers.add(t); return t; };

        // ===================== واجهة الأنميشن =====================
        const style = document.createElement("style");
        style.id = "vr-style";
        style.textContent = `
        #vr-stab{position:fixed;inset:0;z-index:99999;pointer-events:none;font-family:"gg sans",Arial,sans-serif;
            background:transparent;animation:vr-fade .2s forwards}
        #vr-stab video{position:absolute;inset:0;width:100vw;height:100vh;object-fit:cover;background:transparent}
        #vr-stab .bottom{position:absolute;bottom:7vh;left:0;right:0;z-index:2;text-align:center;direction:rtl;unicode-bidi:plaintext;
            opacity:0;animation:vr-txt 2.6s .45s forwards}
        #vr-stab .bottom .who{display:block;font-size:52px;font-weight:900;color:#fff;text-shadow:0 0 16px #f00,0 3px 6px #000}
        #vr-stab .bottom .what{display:block;font-size:30px;font-weight:800;color:#ff6b6b;margin-top:4px;text-shadow:0 2px 6px #000}
        @keyframes vr-fade{0%{opacity:0}100%{opacity:1}}
        @keyframes vr-txt{0%{opacity:0;transform:scale(.7)}12%{opacity:1;transform:scale(1.08)}20%,88%{opacity:1;transform:scale(1)}100%{opacity:0}}

        #vr-move{position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);z-index:99999;min-width:340px;max-width:90vw;
            background:#1e1f22;border:2px solid #5865f2;border-radius:12px;padding:22px 24px;color:#dbdee1;text-align:center;
            font-family:"gg sans",Arial,sans-serif;box-shadow:0 10px 40px rgba(0,0,0,.6);animation:vr-move-in .25s ease-out}
        @keyframes vr-move-in{from{opacity:0;transform:translate(-50%,-50%) scale(.8)}to{opacity:1;transform:translate(-50%,-50%) scale(1)}}
        #vr-move .t{font-size:20px;font-weight:800;margin-bottom:6px;color:#fff}
        #vr-move .t b{color:#ff5a5a}
        #vr-move .s{font-size:15px;margin-bottom:18px;color:#b5bac1}
        #vr-move .btns{display:flex;gap:10px;justify-content:center}
        #vr-move button{border:0;border-radius:6px;padding:10px 18px;font-size:15px;font-weight:700;cursor:pointer;color:#fff}
        #vr-move .back{background:#5865f2}
        #vr-move .stay{background:#4e5058}
        #vr-move .bar{height:3px;background:#5865f2;margin-top:16px;border-radius:2px;animation:vr-bar 20s linear forwards}
        @keyframes vr-bar{from{width:100%}to{width:0}}
        #vr-notice{position:fixed;top:70px;left:50%;transform:translateX(-50%);z-index:99999;pointer-events:none;
            padding:12px 22px;border-radius:8px;background:rgba(20,0,0,.85);border:2px solid #ff4a4a;color:#fff;
            font-family:"gg sans",Arial,sans-serif;font-size:17px;font-weight:700;text-align:center;animation:vr-notice-in .3s ease-out}
        @keyframes vr-notice-in{from{opacity:0;transform:translateX(-50%) translateY(-10px)}to{opacity:1;transform:translateX(-50%)}}

        #vr-net{position:fixed;top:70px;left:50%;transform:translateX(-50%);z-index:99999;pointer-events:none;
            display:flex;align-items:center;gap:14px;padding:10px 20px;background:rgba(0,0,0,.72);
            border:2px solid #f5c400;border-radius:6px;font-family:Consolas,"Courier New",monospace;
            color:#f5c400;font-weight:700;letter-spacing:2px;text-transform:uppercase}
        #vr-net svg{animation:vr-blink 1s steps(2,start) infinite}
        #vr-net span{animation:vr-blink 1s steps(2,start) infinite}
        @keyframes vr-blink{0%{opacity:1}50%{opacity:.12}}`;
        document.head.appendChild(style);

        const VOLUME = 0.7;

        const removeById = (id: string) => { const e = document.getElementById(id); if (e) e.remove(); };

        // صوت احتياطي (يشتغل بس إذا صوت اللقطة انمنع)
        const playSound = () => {
            try {
                const AudioCtx = window.AudioContext || (window as Window & { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
                if (!AudioCtx) return;
                const ctx = new AudioCtx();
                const t0 = ctx.currentTime;
                const g = ctx.createGain();
                g.connect(ctx.destination);
                g.gain.setValueAtTime(VOLUME, t0);
                g.gain.exponentialRampToValueAtTime(0.001, t0 + 0.9);
                const o = ctx.createOscillator();
                o.type = "sine";
                o.frequency.setValueAtTime(180, t0);
                o.frequency.exponentialRampToValueAtTime(40, t0 + 0.6);
                o.connect(g); o.start(t0); o.stop(t0 + 0.9);
                setTimeout(() => ctx.close(), 1500);
            } catch (e) { log("sound failed", e instanceof Error ? e.message : String(e)); }
        };

        // ===================== لقطات الطرد (فيديو شفاف WebM مدمج) =====================
        const SHOT_DATA = [
            "",
            "",
            "",
            ""
        ];
        const SHOT_URLS = SHOT_DATA.map((b64) => {
            try {
                const bin = atob(b64);
                const bytes = new Uint8Array(bin.length);
                for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
                return URL.createObjectURL(new Blob([bytes], { type: "video/webm" }));
            } catch (e) { log("shot decode failed", e instanceof Error ? e.message : String(e)); return null; }
        });
        let lastShot = -1;

        const showStab = (killerName: string, permanent: boolean = false) => {
            removeById("vr-stab");

            // لقطة عشوائية من الأربع، وما تتكرر نفس اللي قبلها
            const n = SHOT_URLS.length;
            let i = Math.floor(Math.random() * n);
            if (n > 1 && i === lastShot) i = (i + 1 + Math.floor(Math.random() * (n - 1))) % n;
            lastShot = i;

            const d = document.createElement("div");
            d.id = "vr-stab";
            d.innerHTML = `<video playsinline preload="auto"></video>
                <div class="bottom"><span class="who"></span><span class="what"></span></div>`;
            const who = d.querySelector<HTMLElement>(".bottom .who");
            if (who) who.textContent = killerName;
            const what = d.querySelector<HTMLElement>(".bottom .what");
            if (what) what.textContent = permanent ? "طردك نهائياً من الغرفة!" : "طردك من الغرفة!";

            const v = d.querySelector<HTMLVideoElement>("video");
            if (!v) return;
            const done = () => removeById("vr-stab");
            v.volume = VOLUME;
            v.onended = () => later(done, 300);
            v.onerror = () => { log("shot failed to load", i + 1); playSound(); };
            const shotUrl = SHOT_URLS[i];
            if (shotUrl) v.src = shotUrl;
            document.body.appendChild(d);

            v.play().catch(() => {
                // لو الصوت انمنع نشغلها بدون صوت مع الصوت الاحتياطي
                v.muted = true;
                v.play().catch(() => { });
                playSound();
            });

            log("stab shot", i + 1);
            later(done, 4000); // احتياط لو ما وصل ended
        };

        const showNet = () => {
            if (document.getElementById("vr-net")) return;
            const d = document.createElement("div");
            d.id = "vr-net";
            d.innerHTML = `<svg width="44" height="44" viewBox="0 0 44 44" fill="none" stroke="#f5c400" stroke-width="3" stroke-linecap="round">
                <path d="M8 36l8-8M28 16l8-8"/><rect x="12" y="24" width="12" height="9" rx="2" transform="rotate(-45 18 28)"/>
                <rect x="20" y="11" width="12" height="9" rx="2" transform="rotate(-45 26 15)"/>
                <path d="M22 22l0 0" /><path d="M4 4l6 6M34 34l6 6"/></svg>
                <span>Connection Interrupted</span>`;
            document.body.appendChild(d);
        };
        const hideNet = () => removeById("vr-net");

        // ===================== مساعدات =====================
        const me = () => UserStore.getCurrentUser();
        const inVoice = () => !!SelectedChannelStore.getVoiceChannelId();

        let rejoinToken = 0;
        const rejoin = (id: string | null, tries: number, token?: number) => {
            if (token === undefined) token = ++rejoinToken; // محاولة جديدة تلغي القديمة
            if (token !== rejoinToken) return;
            if (tries <= 0 || inVoice()) { if (inVoice()) { needNetRejoin = false; hideNet(); } return; }
            if (navigator.onLine !== false && id && ChannelStore.getChannel(id)) {
                log("rejoining", id);
                VoiceActions.selectVoiceChannel(id);
            }
            later(() => rejoin(id, tries - 1, token), 3000);
        };

        const snowflakeTime = (id: string) => Number(BigInt(id) >> BigInt(22)) + 1420070400000;

        // الديسكورد يدمج الطرد المتكرر من نفس الشخص في سجل واحد (يزيد العدّاد فقط)،
        // فنحفظ لقطة للسجل ونقارن العدّاد بدل الاعتماد على الوقت
        const AUDIT_DISCONNECT = 27;
        const AUDIT_MOVE = 26;
        interface AuditEntry {
            id: string;
            user_id?: string;
            options?: { count?: number | string };
        }
        const auditSnap = new Map<string, Map<string, number>>(); // "guildId:type" -> Map(entryId -> count)

        const fetchAudit = async (guildId: string, type: number): Promise<AuditEntry[]> => {
            const res = await RestAPI.get({ url: `/guilds/${guildId}/audit-logs`, query: { action_type: type, limit: 10 } });
            return (res && res.body && res.body.audit_log_entries) || [];
        };
        const countOf = (e: AuditEntry) => Number(e.options && e.options.count) || 1;

        const takeSnapshot = async (guildId: string) => {
            for (const type of [AUDIT_DISCONNECT, AUDIT_MOVE]) {
                try {
                    const m = new Map<string, number>();
                    for (const e of await fetchAudit(guildId, type)) m.set(e.id, countOf(e));
                    auditSnap.set(guildId + ":" + type, m);
                } catch (err) { log("snapshot failed", err instanceof Error ? err.message : String(err)); }
            }
        };

        const findActor = async (guildId: string, type: number, since: number) => {
            try {
                const entries = await fetchAudit(guildId, type);
                const snap = auditSnap.get(guildId + ":" + type);
                let found: string | undefined = undefined;
                for (const e of entries) {
                    const prev = snap ? snap.get(e.id) : undefined;
                    const isNew = snap
                        ? (prev === undefined || countOf(e) > prev)
                        : snowflakeTime(e.id) >= since - 3000;
                    if (isNew && !found) found = e.user_id;
                }
                if (found) {
                    const m = new Map<string, number>();
                    for (const e of entries) m.set(e.id, countOf(e));
                    auditSnap.set(guildId + ":" + type, m);
                }
                return found || null;
            } catch (err) { log("audit log failed", err instanceof Error ? err.message : String(err)); }
            return null;
        };

        const showNotice = (text: string, ms?: number) => {
            removeById("vr-notice");
            const n = document.createElement("div");
            n.id = "vr-notice";
            n.textContent = text;
            document.body.appendChild(n);
            later(() => removeById("vr-notice"), ms || 8000);
        };

        const channelName = (id: string | null) => {
            const c = id && ChannelStore.getChannel(id);
            return c && c.name ? c.name : "الروم";
        };

        const nameOf = async (id: string) => {
            let u = UserStore.getUser(id);
            if (!u) { try { u = await UserUtils.getUser(id); } catch (e) { } }
            return u ? (u.globalName || u.username) : "شخص";
        };

        // طرد نهائي: إذا انطردت مرتين خلال دقيقة، البلوقن ما يرجعك (ولا حتى بعد إعادة التشغيل لمدة 10 دقايق)
        const PERMA_WINDOW = 60 * 1000;
        const BLOCK_KEY = "VoiceReconnect_block";
        let kickTimes: number[] = [];

        const onForcedDisconnect = (guildId: string | null) => {
            const since = Date.now();
            if (navigator.onLine === false) { showNet(); needNetRejoin = true; return; }
            if (!guildId) return;
            const check = (attempt: number) => later(async () => {
                const uid = await findActor(guildId, AUDIT_DISCONNECT, since);
                if (uid && uid !== me().id) {
                    log("disconnected by", uid);
                    const now = Date.now();
                    kickTimes = kickTimes.filter((t) => now - t < PERMA_WINDOW);
                    kickTimes.push(now);
                    const name = await nameOf(uid);
                    if (kickTimes.length >= 2) {
                        log("permanent kick");
                        kickTimes = [];
                        rejoinToken++; // نلغي أي محاولة رجوع شغالة
                        lastChannel = null;
                        try {
                            localStorage.removeItem(KEY);
                            localStorage.setItem(BLOCK_KEY, String(now + 10 * 60 * 1000));
                        } catch (e) { }
                        showStab(name, true);
                        later(() => showNotice(name + " طلّعك نهائياً — البلوقن ما راح يرجعك للروم", 10000), 3300);
                    } else {
                        showStab(name);
                        rejoin(lastChannel, 5);
                    }
                } else if (attempt < 2) check(attempt + 1);
                else if (!inVoice()) {
                    // طلعت بنفسك → لا نرجعك
                    try { localStorage.removeItem(KEY); } catch (e) { }
                    lastChannel = null;
                }
            }, attempt === 0 ? 1500 : 3000);
            check(0);
        };

        const showMovePrompt = (moverName: string, fromId: string, toId: string) => {
            removeById("vr-move");
            const d = document.createElement("div");
            d.id = "vr-move";
            d.innerHTML = `<div class="t"><b></b> نقلك لروم ثاني</div>
                <div class="s"></div>
                <div class="btns"><button class="back"></button><button class="stay">اقعد هنا</button></div>
                <div class="bar"></div>`;
            const tb = d.querySelector(".t b");
            if (tb) tb.textContent = moverName;
            const s = d.querySelector(".s");
            if (s) s.textContent = "من " + channelName(fromId) + " ← إلى " + channelName(toId);
            const backBtn = d.querySelector<HTMLButtonElement>(".back");
            if (backBtn) {
                backBtn.textContent = "ارجع لـ " + channelName(fromId);
                backBtn.onclick = () => {
                    removeById("vr-move");
                    if (ChannelStore.getChannel(fromId)) VoiceActions.selectVoiceChannel(fromId);
                };
            }
            const stayBtn = d.querySelector<HTMLButtonElement>(".stay");
            if (stayBtn) {
                stayBtn.onclick = () => removeById("vr-move");
            }
            document.body.appendChild(d);
            later(() => removeById("vr-move"), 20000);
        };

        const onMoved = (guildId: string | null, fromId: string, toId: string) => {
            const since = Date.now();
            log("moved", fromId, "->", toId);
            const check = (attempt: number) => later(async () => {
                const uid = guildId ? await findActor(guildId, AUDIT_MOVE, since) : null;
                if (uid && uid !== me().id) {
                    showMovePrompt(await nameOf(uid), fromId, toId);
                } else if (attempt < 1) check(attempt + 1);
                else showMovePrompt("أحد", fromId, toId); // ما قدرنا نعرف مين (ما عندك صلاحية Audit Log)
            }, attempt === 0 ? 1200 : 2500);
            check(0);
        };

        // نعرف إذا أنت اللي غيّرت الروم بنفسك
        let selfSelect: { channelId: string | null; at: number } = { channelId: null, at: 0 };
        const onSelfSelect = ({ channelId }: { channelId: string | null }) => { selfSelect = { channelId, at: Date.now() }; };
        FluxDispatcher.subscribe("VOICE_CHANNEL_SELECT", onSelfSelect);

        // ===================== أحداث الفلكس =====================
        interface VoiceStateUpdate {
            userId: string;
            channelId?: string;
            guildId?: string;
        }
        const onVoiceStates = ({ voiceStates }: { voiceStates?: VoiceStateUpdate[] }) => {
            const m = me();
            if (!m || !voiceStates) return;
            for (const s of voiceStates) {
                if (s.userId !== m.id) continue;
                if (s.channelId) {
                    if (s.channelId !== lastChannel) {
                        const bySelf = selfSelect.channelId === s.channelId && Date.now() - selfSelect.at < 8000;
                        if (lastChannel && !bySelf) onMoved(s.guildId || null, lastChannel, s.channelId);
                        else if (s.guildId) takeSnapshot(s.guildId);
                    }
                    lastChannel = s.channelId;
                    lastGuild = s.guildId || null;
                } else if (lastChannel) {
                    const g = lastGuild;
                    onForcedDisconnect(g);
                }
            }
        };
        FluxDispatcher.subscribe("VOICE_STATE_UPDATES", onVoiceStates);

        // ===================== النت =====================
        const onOffline = () => {
            if (lastChannel || inVoice()) {
                if (!lastChannel) lastChannel = SelectedChannelStore.getVoiceChannelId() ?? null;
                needNetRejoin = true;
                showNet();
            }
        };
        const onOnline = () => {
            if (!needNetRejoin) return hideNet();
            later(() => rejoin(lastChannel, 8), 1500);
        };
        window.addEventListener("offline", onOffline);
        window.addEventListener("online", onOnline);

        // ===================== حفظ الروم + الرجوع عند التشغيل =====================
        window.__vrHeartbeat = setInterval(() => {
            const id = SelectedChannelStore.getVoiceChannelId();
            if (id) {
                lastChannel = id;
                try { localStorage.setItem(KEY, JSON.stringify({ channelId: id, ts: Date.now() })); } catch (e) { }
            }
        }, 5000);

        const getTarget = () => {
            try {
                const until = Number(localStorage.getItem(BLOCK_KEY));
                if (until && Date.now() < until) return null;
            } catch (e) { }
            try {
                const m = me();
                const vs = m && VoiceStateStore.getVoiceStateForUser(m.id);
                if (vs && vs.channelId) return vs.channelId as string;
            } catch (e) { }
            try {
                const raw = localStorage.getItem(KEY);
                const saved = raw ? JSON.parse(raw) as { channelId?: string; ts?: number } : null;
                if (saved && saved.ts && saved.channelId && Date.now() - saved.ts < 5 * 60 * 1000) return saved.channelId;
            } catch (e) { }
            return null;
        };

        const startedAt = Date.now();
        let tries = 0;
        let lastTry = 0;

        window.__vrTimer = setInterval(() => {
            if (Date.now() - startedAt > 45000 || tries >= 3) { clearInterval(window.__vrTimer); return; }
            if (Date.now() - lastTry < 3000) return;
            if (inVoice()) { log("already in voice, done"); clearInterval(window.__vrTimer); return; }
            const id = getTarget();
            if (!id || !ChannelStore.getChannel(id)) return;
            tries++;
            lastTry = Date.now();
            log("joining", id, "try", tries);
            VoiceActions.selectVoiceChannel(id);
        }, 300);

        // للتجربة من الكونسول: __vrTest() أو __vrTest("اسم", true)
        window.__vrTest = (name, permanent) => showStab(name || "تجربة", !!permanent);

        window.__vrCleanup = () => {
            FluxDispatcher.unsubscribe("VOICE_STATE_UPDATES", onVoiceStates);
            FluxDispatcher.unsubscribe("VOICE_CHANNEL_SELECT", onSelfSelect);
            window.removeEventListener("offline", onOffline);
            window.removeEventListener("online", onOnline);
            for (const t of timers) clearTimeout(t);
            SHOT_URLS.forEach((u) => { if (u) URL.revokeObjectURL(u); });
            delete window.__vrTest;
            removeById("vr-stab"); removeById("vr-net"); removeById("vr-style"); removeById("vr-move"); removeById("vr-notice");
        };
    },

    stop() {
        clearInterval(window.__vrTimer);
        clearInterval(window.__vrHeartbeat);
        if (window.__vrCleanup) window.__vrCleanup();
    }
});
